const staticData = $getWorkflowStaticData('global');
const histObj = (staticData.historyBySubject && typeof staticData.historyBySubject === 'object') ? staticData.historyBySubject : {};
staticData.historyBySubject = histObj;

const subjects = ['Math', 'Reading & Phonics', 'Science', 'Writing & Grammar', 'Social Studies', 'Art & Coloring', 'Seasonal & Holiday Activities'];
const grades = ['PreK-Grade 1', 'Grade 2-3', 'Grade 4-5'];

// 1 รอบรัน = 1 วิชา — เลื่อนวิชาทุกครั้งที่รัน วนไปเรื่อยๆ
// ครบทั้ง 7 วิชาแล้วค่อยเลื่อนระดับชั้น (Math PreK -> ... -> Seasonal PreK -> Math Grade 2-3 -> ...)
let n = Number.isInteger(staticData.rotation) ? staticData.rotation : 0;
const subject = subjects[n % subjects.length];
const grade = grades[Math.floor(n / subjects.length) % grades.length];
staticData.rotation = n + 1;

let assignment = 'หาเทรนด์ "ธีมภาพวาดการ์ตูน/coloring page" ที่กำลังเป็นที่นิยมบน TPT, Etsy, Pinterest สำหรับใบงานเด็กวิชา ' + subject + ' ระดับ ' + grade + ' แล้วเลือกธีมภาพ + หัวข้อย่อยที่ demand สูงและคู่แข่งน้อยที่สุดตอนนี้ (วิชาและระดับชั้นถูกล็อกแล้ว ห้ามเปลี่ยน แต่ธีมภาพและหัวข้อย่อยให้เลือกเองจากผลการค้นหา)';
const hist = Array.isArray(histObj[subject]) ? histObj[subject] : [];
if (hist.length > 0) {
  assignment += '\n\n**สำคัญมาก - ห้ามทำซ้ำ**: วิชานี้เคยสร้างธีม/หัวข้อต่อไปนี้ไปแล้ว ห้ามเลือกที่เหมือนหรือใกล้เคียงเด็ดขาด:\n- ' + hist.slice(-40).join('\n- ');
}

return [{
  json: {
    chatInput: assignment,
    sessionId: 'auto-' + new Date().toISOString().slice(0, 10) + '-' + n,
    subject: subject,
    grade: grade
  }
}];

