// QA Gate (Drawing Edition) — ตรวจโครงชุดใบงานแบบภาพวาดก่อนเสียเงินเจนภาพ
// ไม่ผ่าน -> ส่ง qa_notes กลับ Agent 3 แก้ 1 รอบ แล้ว force-pass กัน pipeline ค้าง
const MAX_RETRIES = 1;
const attempt = (typeof $runIndex !== 'undefined' && $runIndex != null) ? $runIndex : 0;

let data = null;
try { data = $('3. Content Creation Agent').last().json.output; } catch (e) {}

const problems = [];
const FULL = ['color_by_number_scene', 'color_mixing_scene', 'board_game', 'coloring_scene'];
const GRID = ['picture_grid', 'count_and_write'];
const KEYED = ['color_by_number_scene', 'color_mixing_scene'];
const BASE_COLORS = ['red', 'blue', 'yellow', 'white', 'black'];

if (!data || !data.title || !Array.isArray(data.pages) || data.pages.length === 0) {
  problems.push('No valid title/pages returned — regenerate the full worksheet JSON.');
} else {
  const pages = data.pages;
  if (pages.length < 7 || pages.length > 8) problems.push('Pack has ' + pages.length + ' pages; make 8 pages total (7 activity pages + the final answer_key).');
  const lastType = String((pages[pages.length - 1] || {}).activity_type || '').toLowerCase();
  if (lastType !== 'answer_key') problems.push('The LAST page must be activity_type "answer_key".');
  if (!data.mascot_prompt) problems.push('mascot_prompt is missing.');
  if (!data.cover_hint) problems.push('cover_hint is missing.');

  let imageJobs = 2; // cover + mascot
  pages.forEach((p, idx) => {
    const t = String(p.activity_type || '').toLowerCase();
    const items = Array.isArray(p.items) ? p.items : [];
    const label = 'Page ' + (idx + 1) + ' ("' + (p.page_title || '') + '", ' + t + ')';

    if (t === 'answer_key') {
      if (items.length === 0) problems.push(label + ' must list the answers for every page.');
      // เฉลยต้องครบทุกหน้ากิจกรรม (Page 1 .. Page N-1)
      for (let pi = 1; pi < pages.length; pi++) {
        if (!items.some(it => String(it).includes('Page ' + pi))) {
          problems.push('Answer key is MISSING the answers for Page ' + pi + ' — include one line per activity page, each starting with "Page ' + pi + ' (title): ...". Open-ended pages still need a line saying "open-ended".');
        }
      }
      return;
    }
    if (!FULL.includes(t) && !GRID.includes(t)) problems.push(label + ': unknown activity_type — use only color_by_number_scene, color_mixing_scene, picture_grid, board_game, coloring_scene, count_and_write, answer_key.');
    if (!p.scene_prompt || String(p.scene_prompt).length < 40) problems.push(label + ': scene_prompt is missing or too short — write a detailed English image prompt (2-3 sentences).');
    imageJobs += 1;

    if (/\b(colorful|vibrant|red|blue|green|yellow|orange|purple|pink)\b/i.test(String(p.scene_prompt || '')) && !KEYED.includes(t)) {
      problems.push(label + ': scene_prompt mentions colors — inside pages must be pure black-and-white line art, remove color words.');
    }
    // ห้ามใส่โจทย์ลงใน scene_prompt ทุกประเภท — ระบบเป็นคนพิมพ์โจทย์ทับภาพเอง (KEYED) หรือหน้านั้นไม่ควรมีโจทย์ในภาพเลย (อื่นๆ)
    if (/\d\s*[+xX×*]\s*\d/.test(String(p.scene_prompt || ''))) {
      problems.push(label + ': scene_prompt contains a math fact — NEVER put facts/numbers in scene_prompt. The system prints the facts onto empty badges itself; describe the scene only.');
    }
    if (!KEYED.includes(t) && /\d\s*[+xX×*]\s*\d/.test(String(p.instructions || ''))) {
      problems.push(label + ': instructions embed math facts but this page is not color_by_number_scene/color_mixing_scene — change the activity_type or remove the facts.');
    }
    if (t === 'color_by_number_scene') {
      const key = Array.isArray(p.color_key) ? p.color_key : [];
      if (key.length < 5 || key.length > 8) problems.push(label + ': color_key must have 5-8 entries of {answer, color}.');
      // facts ต้องมีโครงสร้าง + คำนวณแล้วคำตอบอยู่ใน key จริง + ถูกสั่งฝังใน scene_prompt
      const facts = Array.isArray(p.facts) ? p.facts : [];
      if (facts.length < 4 || facts.length > 8) problems.push(label + ': provide 4-8 exact fact strings in the "facts" array — the same strings written inside the picture.');
      if (new Set(facts.map(f => String(f).replace(/\s+/g, ''))).size !== facts.length) problems.push(label + ': facts contains duplicates — every fact must be unique.');
      const answers = key.map(k => String(k.answer).trim());
      // ทุกสีใน key ต้องมีโจทย์อย่างน้อย 1 ข้อที่ให้คำตอบนั้น (กันสีเกินค้างเติ่งแบบ 9=yellow ที่ไม่มีโจทย์)
      const factVals = facts.map(f => {
        const m = String(f).replace(/\s+/g, '').match(/^(\d+)([+\-xX×*])(\d+)$/);
        if (!m) return null;
        const a = +m[1], b = +m[3], op = m[2].toLowerCase();
        return String(op === '+' ? a + b : (op === '-' ? a - b : a * b));
      });
      answers.forEach(ans => {
        if (!factVals.includes(ans)) problems.push(label + ': color_key answer ' + ans + ' has NO fact producing it — every key color must be used by at least one fact (or remove it from the key).');
      });
      facts.forEach(f => {
        const m = String(f).replace(/\s+/g, '').match(/^(\d+)([+\-xX×*])(\d+)$/);
        if (!m) { problems.push(label + ': fact "' + f + '" must look like "3+4", "9-2" or "3x4".'); return; }
        const a = +m[1], b = +m[3], op = m[2].toLowerCase();
        const val = op === '+' ? a + b : (op === '-' ? a - b : a * b);
        if (!answers.includes(String(val))) problems.push(label + ': fact "' + f + '" = ' + val + ' but ' + val + ' is not among the color_key answers (' + answers.join(', ') + ') — every fact answer must exist in the key so kids can color it.');
      });
    }
    if (t === 'color_mixing_scene') {
      const key = Array.isArray(p.color_key) ? p.color_key : [];
      const mixes = Array.isArray(p.mix_key) ? p.mix_key : [];
      if (key.length < 2 || key.length > 4) problems.push(label + ': color_key (base paint colors) must have 2-4 entries.');
      key.forEach(k => {
        if (!BASE_COLORS.includes(String(k.color || '').toLowerCase().trim())) problems.push(label + ': base color "' + k.color + '" not allowed — use only red, blue, yellow, white, black.');
      });
      if (mixes.length < 4 || mixes.length > 8) problems.push(label + ': mix_key must have 4-8 entries of {fact, mix, result, object}.');
      if (new Set(mixes.map(m => String((m || {}).object || '') + '|' + String((m || {}).fact || ''))).size !== mixes.length) problems.push(label + ': mix_key contains duplicate object+fact pairs — each entry must be unique.');

      // ตารางผสมสีจริง: คู่แม่สี (เรียงตามตัวอักษร) -> ผลผสมที่ยอมรับ
      const MIX_TABLE = {
        'red|yellow': ['orange'],
        'blue|red': ['purple', 'violet'],
        'blue|yellow': ['green'],
        'red|white': ['pink'],
        'blue|white': ['light blue', 'lightblue', 'sky blue'],
        'black|white': ['gray', 'grey'],
        'black|red': ['brown', 'dark red', 'darkred', 'maroon']
      };
      const numToColor = {};
      key.forEach(k => { numToColor[String(k.answer).trim()] = String(k.color || '').toLowerCase().trim(); });

      const HOWTO = ' HOW TO BUILD color_mixing_scene: the numbers in each fact are the KEY NUMBERS of the two base colors that mix into the object\'s natural color — NOT a sum to look up. Example: carrot is orange; orange = red + yellow; if key has 1=red and 2=yellow then the carrot fact must be "1+2".';

      mixes.forEach(m => {
        if (!m || !m.fact || !m.mix || !m.result) { problems.push(label + ': every mix_key entry needs fact, mix, result, object.' + HOWTO); return; }
        const fm = String(m.fact).match(/^\s*(\S+)\s*\+\s*(\S+)\s*$/);
        if (!fm) { problems.push(label + ': fact "' + m.fact + '" must look like "1+2".'); return; }
        const cA = numToColor[fm[1]], cB = numToColor[fm[2]];
        if (!cA || !cB) { problems.push(label + ': fact "' + m.fact + '" uses numbers that are not in color_key — every number in a fact must be a base-color number from the key.' + HOWTO); return; }
        const pair = [cA, cB].sort().join('|');
        const allowed = MIX_TABLE[pair];
        const result = String(m.result || '').toLowerCase().trim();
        if (!allowed) { problems.push(label + ': fact "' + m.fact + '" mixes ' + cA + ' + ' + cB + ' which is not an allowed real-paint pair. Allowed: red+yellow=orange, red+blue=purple, blue+yellow=green, red+white=pink, blue+white=light blue, black+white=gray, red+black=brown.' + HOWTO); return; }
        if (!allowed.includes(result)) { problems.push(label + ': fact "' + m.fact + '" (' + cA + ' + ' + cB + ') must give "' + allowed[0] + '" but result says "' + m.result + '".' + HOWTO); return; }
        const mixLower = String(m.mix).toLowerCase();
        if (!mixLower.includes(cA) || !mixLower.includes(cB)) problems.push(label + ': mix "' + m.mix + '" does not match the fact colors (' + cA + ' + ' + cB + ').');
        if (m.object && !String(p.scene_prompt || '').toLowerCase().includes(String(m.object).toLowerCase().split(' ').pop())) problems.push(label + ': object "' + m.object + '" is not described in scene_prompt — the scene must clearly contain every mix_key object.');
      });
    }
    if (GRID.includes(t)) {
      if (items.length < 4 || items.length > 8) problems.push(label + ': grid pages need 4-8 numbered items (one per panel in the picture).');
      // จับ filler: ทุกข้อเป็นประโยคเดิมเป๊ะ ต่างแค่เลขข้อ และไม่มีข้อมูลโจทย์จริง (ตัวเลข >= 2 กลุ่ม หรือช่องเติม __ ถือว่ามีเนื้อหา)
      if (items.length >= 3) {
        const norm = items.map(it => String(it).toLowerCase().replace(/\d+/g, '#').replace(/\s+/g, ' ').trim());
        const hasRealContent = items.every(it => (String(it).match(/\d+/g) || []).length >= 2 || String(it).includes('__'));
        if (new Set(norm).size === 1 && !hasRealContent) problems.push(label + ': items are repetitive filler — every item is the same sentence with only the panel number changed and carries no real problem data. Each item must contain the REAL problem content so it can be solved from the text alone, e.g. "1. Fill in: 5, __, __, 8" or "1. 9-2 = __ vs 7-1 = __ — circle the greater answer".');
      }
    }
    items.forEach(it => { if (String(it).length > 90) problems.push(label + ': an item is ' + String(it).length + ' chars — keep every item under 90 chars.'); });
  });

  if (imageJobs < 8 || imageJobs > 9) problems.push('Total images would be ' + imageJobs + ' (cover + mascot + 1 per activity page). The target is 9 (i.e. 7 activity pages with one image each).');
}

let pass = problems.length === 0;
let forced = false;
if (!pass && attempt >= MAX_RETRIES) { pass = true; forced = true; }

return [{ json: {
  qa_pass: pass,
  qa_forced: forced,
  qa_attempt: attempt,
  qa_notes: problems.length ? ('- ' + problems.join('\n- ')) : ''
} }];

const data = $('3. Content Creation Agent').last().json.output;
if (!data || !data.title || !Array.isArray(data.pages) || data.pages.length === 0) {
  throw new Error('Content Agent ไม่ได้ส่ง title/pages ที่ถูกต้อง ข้อมูลที่ได้: ' + JSON.stringify($json).slice(0, 300));
}

// สไตล์บังคับสำหรับภาพหน้าใน (ขาวดำล้วน) — เติมท้ายทุก prompt อัตโนมัติ
const BW_STYLE = '. Black and white line art ONLY, thick bold clean outlines, cute kawaii cartoon style for kids, pure white background, no shading, no gray tones, absolutely no color. The artwork should fill most of the canvas, but keep every important element fully inside the frame with a small safe margin from all four edges — nothing may be cut off at the canvas borders.';
const GRID = ['picture_grid', 'count_and_write'];
const KEYED = ['color_by_number_scene', 'color_mixing_scene'];

const jobs = [];

// 1 รูปสี: หน้าปก
jobs.push({
  job_id: 'cover',
  prompt: 'Colorful cover art for a children\'s educational worksheet pack titled "' + data.title + '". ' + (data.cover_hint || '') + ' Cute flat vector clipart style for teachers, bright cheerful colors, clean uncluttered composition, artwork filling the whole canvas, and large clear bold title text near the top that reads exactly: ' + data.title + '. Keep the title text and main characters comfortably away from the outer edges of the image.',
  size: '1024x1536',
  quality: 'medium'
});

// mascot ขาวดำ ติดมุมทุกหน้า
jobs.push({
  job_id: 'mascot',
  prompt: 'A single cute cartoon mascot for a kids worksheet, one simple character centered, no text or letters anywhere' + BW_STYLE + ' The mascot is: ' + (data.mascot_prompt || 'a happy pencil holding a book'),
  size: '1024x1024',
  quality: 'low'
});

// 1 รูปขาวดำต่อหน้ากิจกรรม — สัดส่วนภาพจับคู่กับพื้นที่จริงบนหน้ากระดาษ:
// เต็มหน้า = จัตุรัส 1024x1024 (พื้นที่หลังหักหัวกระดาษ ~7.3x7.5in), ตาราง = แนวนอน 1536x1024 (เหลือที่ให้โจทย์ใต้ภาพ)
data.pages.forEach((p, idx) => {
  const t = String(p.activity_type || '').toLowerCase();
  if (t === 'answer_key' || !p.scene_prompt) return;
  // คุมข้อความในภาพตามประเภท — กันเลขมั่ว/ข้อความหลง
  let textRule;
  if (GRID.includes(t)) {
    textRule = ' The ONLY text allowed in the image is one big panel number label (1, 2, 3, ...) in the corner of each panel — absolutely NO other numbers, letters, words or math facts anywhere in the image.';
  } else if (t === 'board_game') {
    textRule = ' Do NOT write any numbers, letters, words or symbols in the image other than the exact labels explicitly requested above.';
  } else {
    // coloring_scene และหน้าโจทย์ (ระบบพิมพ์โจทย์ทับเอง): ห้ามมีข้อความใดๆ ในภาพ
    textRule = ' Absolutely NO text, numbers or letters anywhere in the image.';
  }
  // หน้าโจทย์: ไม่ให้ AI เขียนเลขเอง — สั่งวาด "วงกลมป้ายว่าง" แล้วระบบพิมพ์โจทย์ทับทีหลัง (แม่น 100%)
  let expectedFacts = [];
  let badgeRule = '';
  if (t === 'color_by_number_scene') {
    expectedFacts = Array.isArray(p.facts) ? p.facts : [];
    badgeRule = ' The scene must include EXACTLY ' + expectedFacts.length + ' large plain EMPTY circular badges (blank white circles with a bold outline, at least 1/8 of the image wide), distributed on the main objects/sections of the scene, completely blank inside — math problems will be printed into them later.';
  } else if (t === 'color_mixing_scene') {
    const mixes = Array.isArray(p.mix_key) ? p.mix_key : [];
    expectedFacts = mixes.map(m => m && m.fact).filter(Boolean);
    const objs = mixes.map(m => (m && m.object) || 'object');
    badgeRule = ' The scene must include EXACTLY ' + expectedFacts.length + ' large plain EMPTY circular badges (blank white circles with a bold outline, at least 1/8 of the image wide), completely blank inside: one badge placed on the ' + objs.join(', one on the ') + '. Math codes will be printed into them later.';
  }

  jobs.push({
    job_id: 'page_' + idx,
    prompt: String(p.scene_prompt) + BW_STYLE + badgeRule + textRule,
    size: GRID.includes(t) ? '1536x1024' : '1024x1024',
    quality: KEYED.includes(t) ? 'high' : 'medium',
    expected_facts: expectedFacts
  });
});

return jobs.map(j => ({ json: j }));

// จับคู่ผลลัพธ์ภาพกลับเข้า job_id (ลำดับ item ตรงกับ Extract Image Jobs เพราะ HTTP node รันทีละ item)
const jobs = $('Extract Image Jobs').all().map(i => i.json);
const responses = $input.all().map(i => i.json);

const images = {};
jobs.forEach((job, i) => {
  const r = responses[i] || {};
  images[job.job_id] = (r.data && r.data[0] && r.data[0].b64_json) || '';
});

const ok = Object.values(images).filter(Boolean).length;
return [{ json: { images: images, attempt: 0, images_ok: ok, images_total: jobs.length } }];

// Image QA 2 ชั้น — (1) ภาพครบทุก job ไหม (2) Vision อ่านตัวเลขโจทย์ในภาพจริง เทียบกับที่สั่ง
// ภาพที่หาย/ตัวเลขเพี้ยน จะถูกส่งไปเจนใหม่ (วนซ้ำ 1 รอบ) — ไม่แบก images map ใน output เพื่อประหยัดแรม
const MAX_IMG_RETRIES = 2;
const jobs = $('Extract Image Jobs').all().map(i => i.json);
const images = $json.images || {};
const attempt = Number.isInteger($json.attempt) ? $json.attempt : 0;

const missing = jobs.filter(j => !images[j.job_id]);

// ---- ชั้น Vision: เฉพาะหน้าโจทย์ (expected_facts) — นับวงกลมป้ายว่าง + หาพิกัด + เช็คว่าไม่มีข้อความหลง ----
// ระบบจะพิมพ์โจทย์ทับลงพิกัดวงกลมด้วยฟอนต์จริงตอนประกอบ HTML (ตัวเลขแม่น 100%)
const visionFailed = [];
const badgeMap = {};
for (const j of jobs) {
  const expected = Array.isArray(j.expected_facts) ? j.expected_facts : [];
  if (!expected.length) continue;
  const b64 = images[j.job_id];
  if (!b64) continue;
  try {
    const resp = await this.helpers.httpRequest({
      url: 'https://api.openai.com/v1/chat/completions',
      method: 'POST',
      headers: { 'Authorization': 'Bearer YOUR_OPENAI_API_KEY', 'Content-Type': 'application/json' },
      body: {
        model: 'gpt-5-mini',
        messages: [{ role: 'user', content: [
          { type: 'text', text: 'This black-and-white children\'s worksheet illustration should contain EXACTLY ' + expected.length + ' large EMPTY circular badges (blank circles with bold outlines) and NO text at all. Reply ONLY with JSON: {"badges": [{"x": <badge center x as percent 0-100 of image width>, "y": <center y as percent 0-100 of image height>, "r": <radius as percent of image width>, "object": "<short name of the object this badge sits on>"}], "stray_text": ["<every piece of text, numbers or letters visible in the image, if any>"]}' },
          { type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + b64, detail: 'high' } }
        ] }],
        response_format: { type: 'json_object' },
        max_completion_tokens: 700
      },
      json: true,
      timeout: 90000
    });
    const parsed = JSON.parse(resp.choices[0].message.content);
    const badges = Array.isArray(parsed.badges) ? parsed.badges.filter(b => b && isFinite(+b.x) && isFinite(+b.y)) : [];
    const stray = Array.isArray(parsed.stray_text) ? parsed.stray_text.filter(s => String(s).trim()) : [];
