function overlayFacts(pageIdx, p, t, sideIn) {
  const isMix = t === 'color_mixing_scene';
  const factList = isMix
    ? (Array.isArray(p.mix_key) ? p.mix_key : []).map(m => ({ f: String((m || {}).fact || ''), obj: String((m || {}).object || '').toLowerCase() }))
    : (Array.isArray(p.facts) ? p.facts : []).map(f => ({ f: String(f), obj: '' }));
  if (!factList.length) return '';

  let badges = (badgeMap['page_' + pageIdx] || []).slice();
  if (badges.length !== factList.length) {
    // fallback: วางเรียงสลับสูง-ต่ำกลางภาพ (ตัวเลขยังถูก 100% แค่ตำแหน่งไม่อิงวงกลม)
    badges = factList.map((_, i2) => ({ x: (100 / (factList.length + 1)) * (i2 + 1), y: i2 % 2 ? 63 : 37, r: 8, object: '' }));
  }
  badges.sort((a, b) => (a.y - b.y) || (a.x - b.x));

  // จับคู่โจทย์กับป้าย: mixing จับตามชื่อวัตถุก่อน ที่เหลือเรียงตามลำดับอ่าน
  const assigned = new Array(badges.length).fill(-1);
  const used = new Set();
  if (isMix) {
    badges.forEach((b, bi) => {
      const bo = String(b.object || '').toLowerCase();
      if (!bo) return;
      for (let fi = 0; fi < factList.length; fi++) {
        if (used.has(fi)) continue;
        const kw = factList[fi].obj.split(' ').pop();
        if (kw && bo.includes(kw)) { assigned[bi] = fi; used.add(fi); break; }
      }
    });
  }
  for (let bi = 0, fi = 0; bi < badges.length; bi++) {
    if (assigned[bi] >= 0) continue;
    while (fi < factList.length && used.has(fi)) fi++;
    if (fi >= factList.length) break;
    assigned[bi] = fi; used.add(fi); fi++;
  }

  const sidePx = sideIn * 96;
  return badges.map((b, bi) => {
    if (assigned[bi] < 0) return '';
    const wPct = Math.max(9, Math.min(26, (+b.r || 8) * 2));
    const fs = Math.round(Math.max(13, Math.min(38, (wPct / 100) * sidePx * 0.33)));
    return `<div class='fact-ovl' style='left:${(+b.x).toFixed(1)}%;top:${(+b.y).toFixed(1)}%;width:${wPct}%;font-size:${fs}px'>${esc(factList[assigned[bi]].f)}</div>`;
  }).join('');
}

